"""Real injected HTML; backend-generated grades and mocked Google transport, no live writes."""
import csv,io,json,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[2]; REPO=ROOT.parents[1]
script=r"""import {nilaiAkhirHarness} from './apps-script/absensi-dashboard/tests/support/nilai-akhir-harness.mjs';import {plain} from './apps-script/absensi-dashboard/tests/support/rekap-evaluasi-harness.mjs';const h=nilaiAkhirHarness();h.fill();const f={html:{Index:h.t.c.keluaranAplikasiPanitia_('Index','Monitoring').content,Profil:h.t.c.keluaranAplikasiPanitia_('Profil','Profil').content},roles:{},responses:{},stages:{}};for(const [name,actor] of Object.entries({admin:h.admin,staff:h.staff,teacher:h.teacher})){f.roles[name]={login:actor,identity:h.t.c.muatSesiAplikasiPanitia(actor.token)};f.responses[name]={};for(const rpc of ['muatAwalIndex','muatKehadiranIndex','muatNilaiPerilakuProgramIndex','muatCatatanPerilakuIndex','muatDaftarIzinIndex','muatDaftarVerifikasiSesiPanitia','muatPengajuanKoreksiPanitia']){try{f.responses[name][rpc]=h.call(actor,rpc,...(rpc==='muatAwalIndex'||rpc.includes('Verifikasi')||rpc.includes('Pengajuan')?[]:rpc.includes('ProgramIndex')?['PRG001']:['SES001']));}catch(e){f.responses[name][rpc]={sukses:true,pengajuan:[],sesi:[]};}}f.responses[name].muatRekapJPProgramIndex=h.result(actor);f.responses[name].muatProfilPesertaIndex=h.call(actor,'muatProfilPesertaIndex',{id_keikutsertaan:'KST001'});}f.weights=h.weights();f.stages.complete=h.result();h.saveWeights();f.stages.weighted=h.result();h.absent('izin');f.stages.absent=h.result();h.t.h.patch('Peserta','PST001','id_peserta',{nama_pegawai:'Nama berubah'});f.stages.missing=h.result();f.stages.error={...h.result(),nilai_akhir:{sukses:false,tersedia:false,pesan:'Jurnal evaluasi tidak dapat dibaca'}};process.stdout.write(JSON.stringify(plain(f)));"""
f=json.loads(subprocess.check_output(['node','--input-type=module','-e',script],cwd=REPO,text=True))
mock=r'''
window.F=FIXTURE;window.calls=[];window.stage='complete';window.hold=false;window.fail=false;window.pending=[];
const actor=F.roles[ROLE];localStorage.setItem(actor.login.storage_key,JSON.stringify({token:actor.login.token,expires:actor.identity.expires}));
function result(name,arg){if(name==='muatSesiAplikasiPanitia')return actor.identity;if(name==='panggilBacaanDashboardPanitia')return {sukses:true,hasil:arg.permintaan.map(p=>({sukses:true,data:result('panggilAplikasiPanitia',{nama:p.nama,args:p.args})}))};if(name!=='panggilAplikasiPanitia')throw Error('Unexpected '+name);if(arg.nama==='muatBobotNilaiAkhirIndex')return F.weights;if(arg.nama==='simpanBobotNilaiAkhirIndex'){if(window.fail){window.fail=false;throw Error('Respons terputus');}window.stage='weighted';return {sukses:true,pesan:'Bobot nilai akhir tersimpan.'};}if(arg.nama==='muatRekapJPProgramIndex'&&ROLE==='admin')return F.stages[window.stage];if(F.responses[ROLE][arg.nama])return JSON.parse(JSON.stringify(F.responses[ROLE][arg.nama]));throw Error('No fixture '+arg.nama);}
function bridge(ok,bad){return new Proxy({}, {get(t,name){if(name==='withSuccessHandler')return fn=>bridge(fn,bad);if(name==='withFailureHandler')return fn=>bridge(ok,fn);return arg=>{calls.push({name,arg:JSON.parse(JSON.stringify(arg??null))});const work=()=>{try{ok?.(result(name,arg));}catch(e){bad?.(e);}};if(name==='panggilAplikasiPanitia'&&arg.nama==='simpanBobotNilaiAkhirIndex'&&window.hold)pending.push(work);else setTimeout(work,10);};}});}
window.google={script:{run:bridge(),history:{replace(){}},host:{close(){}},url:{getLocation(fn){fn({parameter:{page:PAGE,program:'PRG001',jenjang:'JEN001',sesi:'SES001',keikutsertaan:'KST001'}});}}}};
'''
out=Path('/tmp/nilai-akhir-preview');out.mkdir(exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 def open_page(role='admin',width=1440,kind='Index'):
  page=b.new_page(viewport={'width':width,'height':1000},accept_downloads=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script(mock.replace('ROLE',json.dumps(role)).replace('PAGE',json.dumps('profil' if kind=='Profil' else 'monitoring')).replace('FIXTURE',json.dumps(f)))
  page.route('**/*',lambda r:r.fulfill(status=200,content_type='text/html',body=f['html'][kind]) if r.request.resource_type=='document' else r.abort());page.goto('https://script.google.com/macros/s/COPY/exec?page=monitoring&program=PRG001&jenjang=JEN001&sesi=SES001&keikutsertaan=KST001')
  expect(page.locator('#panitiaAuth')).not_to_be_visible();return page,errors
 page,errors=open_page();page.locator('#tabRekap').click();expect(page.locator('#recapFinalInfo')).to_contain_text('60%');row=page.locator('#recapBody tr').filter(has_text='KST001');expect(row).to_contain_text('84,00');expect(row).to_contain_text('Data lengkap');row.get_by_role('button',name='Rincian Nilai').click();expect(page.locator('#finalScoreBody tr')).to_have_count(2);expect(page.locator('#finalScoreBody')).to_contain_text('Praktik lanjutan');page.locator('#closeFinalScore').click()
 with page.expect_download() as download:page.locator('#downloadRecap').click()
 records=list(csv.DictReader(io.StringIO(Path(download.value.path()).read_text(encoding='utf-8-sig'))));assert len(records[0])==23;assert records[0]['nilai_keseluruhan']=='84';assert records[0]['status_nilai_keseluruhan']=='lengkap'
 page.locator('#openFinalWeights').click();expect(page.locator('#finalTeacherWeight')).to_have_value('60');page.locator('#finalTeacherWeight').fill('70');expect(page.locator('#finalStaffWeight')).to_have_value('30');page.locator('#saveFinalWeights').click();assert not page.evaluate("calls.some(c=>c.arg?.nama==='simpanBobotNilaiAkhirIndex')");page.locator('#finalWeightsReason').fill('Aturan program uji');page.evaluate('window.hold=true;window.fail=true');page.locator('#saveFinalWeights').click();expect(page.locator('#closeFinalWeights')).to_be_disabled();page.keyboard.press('Escape');expect(page.locator('#finalWeightsDialog')).to_be_visible();page.evaluate('window.hold=false;pending.splice(0).forEach(fn=>fn())');expect(page.locator('#finalWeightsMessage')).to_contain_text('Respons terputus');expect(page.locator('#finalTeacherWeight')).to_be_disabled();page.locator('#saveFinalWeights').click();expect(page.locator('#finalWeightsDialog')).not_to_be_visible();expect(row).to_contain_text('83,00');expect(page.locator('#recapFinalInfo')).to_contain_text('70%');requests=page.evaluate("calls.filter(c=>c.arg?.nama==='simpanBobotNilaiAkhirIndex').map(c=>c.arg.args[0])");assert len(requests)==2 and requests[0]==requests[1]
 page.evaluate("window.stage='absent'");page.locator('#refreshRecap').click();expect(row).to_contain_text('94,00');row.get_by_role('button',name='Rincian Nilai').click();expect(page.locator('#finalScoreSummary')).to_contain_text('1 sesi Tidak Dinilai');expect(page.locator('#finalScoreBody')).to_contain_text('Tidak Dinilai: izin');page.screenshot(path=str(out/'Nilai-Akhir-Rincian.png'));page.locator('#closeFinalScore').click()
 page.evaluate("window.stage='missing'");page.locator('#refreshRecap').click();expect(row).to_contain_text('Sementara');final=row.locator('td').last;expect(final.locator('strong')).to_have_text('—')
 with page.expect_download() as download:page.locator('#downloadRecap').click()
 records=list(csv.DictReader(io.StringIO(Path(download.value.path()).read_text(encoding='utf-8-sig'))));assert records[0]['nilai_keseluruhan']=='';assert records[0]['status_nilai_keseluruhan']=='sementara'
 page.evaluate("window.stage='error'");page.locator('#refreshRecap').click();expect(page.locator('#recapInfo')).to_contain_text('Jurnal evaluasi tidak dapat dibaca');expect(page.locator('#downloadRecap')).to_be_disabled();assert not errors,errors;page.close()
 staff,errors=open_page('staff',390);staff.locator('#tabRekap').click();expect(staff.locator('#recapBody')).to_contain_text('84,00');expect(staff.locator('#openFinalWeights')).not_to_be_visible();staff.locator('#recapBody').get_by_role('button',name='Rincian Nilai').click();expect(staff.locator('#finalScoreDialog')).to_be_visible();assert staff.locator('#finalScoreDialog').evaluate('e=>e.getBoundingClientRect().width')<=390;assert staff.evaluate('document.documentElement.scrollWidth<=innerWidth');staff.screenshot(path=str(out/'Nilai-Akhir-Mobile.png'));assert not errors,errors;staff.close()
 teacher,errors=open_page('teacher');teacher.locator('#tabRekap').click();expect(teacher.locator('#recapBody')).to_be_visible();expect(teacher.locator('#openFinalWeights')).not_to_be_visible();assert teacher.locator('#recapBody').get_by_role('button',name='Rincian Nilai').count()==0;assert not errors,errors;teacher.close()
 profile,errors=open_page('staff',kind='Profil');expect(profile.locator('#profileFinalValue')).to_contain_text('84,00');expect(profile.locator('#profileFinalBasis')).to_contain_text('60%');assert not errors,errors;profile.close();b.close()
print('PASS: live final grades/details, exact 23-column CSV, absence and missing values, source failure blocks export, Admin weight modal + same-ID retry, staff scope/mobile, teacher privacy and profile; Google mocked.')
